INSERT INTO public.articles (id,title,title_ar,title_en,slug,content,content_ar,content_en,summary,summary_ar,summary_en,author,tags,featured,published,views,metadata) VALUES ('84f326fc-54eb-5010-a5d8-788dce7829a1','آداب تلاوة القرآن وبناء ورد ثابت','آداب تلاوة القرآن وبناء ورد ثابت','Zikr Educational Article','zikr-article-deep-01','تبدأ تلاوة القرآن بالنية الصالحة واحترام كلام الله، ثم باختيار مقدار يمكن المحافظة عليه دون انقطاع. لا يقاس النجاح بعدد الصفحات وحده؛ فالفهم، وحضور القلب، ومراجعة المعنى، والعمل بما يتعلمه القارئ عناصر متكاملة. يمكن تقسيم الورد إلى جلسة قصيرة بعد الفجر وأخرى قبل النوم، مع استخدام المصحف الورقي أو الرقمي الذي ييسر التركيز. عند صعوبة لفظ أو معنى، يرجع القارئ إلى قراءة الآية من مصدر موثوق وإلى تفسير معتمد، ولا يبني حكمًا تفصيليًا على فهم سريع أو ترجمة آلية. ومن المفيد تسجيل السورة والآيات التي توقّف عندها القارئ، ثم العودة إليها في نهاية الأسبوع. هذا الأسلوب يجعل القراءة مشروع تعلم مستمرًا، ويحميها من التحول إلى عادة سريعة بلا تدبر أو مراجعة.','تبدأ تلاوة القرآن بالنية الصالحة واحترام كلام الله، ثم باختيار مقدار يمكن المحافظة عليه دون انقطاع. لا يقاس النجاح بعدد الصفحات وحده؛ فالفهم، وحضور القلب، ومراجعة المعنى، والعمل بما يتعلمه القارئ عناصر متكاملة. يمكن تقسيم الورد إلى جلسة قصيرة بعد الفجر وأخرى قبل النوم، مع استخدام المصحف الورقي أو الرقمي الذي ييسر التركيز. عند صعوبة لفظ أو معنى، يرجع القارئ إلى قراءة الآية من مصدر موثوق وإلى تفسير معتمد، ولا يبني حكمًا تفصيليًا على فهم سريع أو ترجمة آلية. ومن المفيد تسجيل السورة والآيات التي توقّف عندها القارئ، ثم العودة إليها في نهاية الأسبوع. هذا الأسلوب يجعل القراءة مشروع تعلم مستمرًا، ويحميها من التحول إلى عادة سريعة بلا تدبر أو مراجعة.',NULL,'دليل عملي لبناء ورد قرآني ثابت يجمع القراءة والفهم والعمل دون ادعاء تفسير ذاتي.','دليل عملي لبناء ورد قرآني ثابت يجمع القراءة والفهم والعمل دون ادعاء تفسير ذاتي.',NULL,'فريق تحرير ذِكر',ARRAY['القرآن','التدبر','العبادة'],false,true,0,'{"editorial": true, "not_hadith_quote": true, "not_fatwa": true, "source_urls": ["https://quran.com/2/121", "https://quran.com/47/24"], "source_note": "Original educational article; readers should consult primary sources and qualified scholars for detailed rulings."}'::jsonb) ON CONFLICT (slug) DO UPDATE SET title=excluded.title,title_ar=excluded.title_ar,title_en=excluded.title_en,content=excluded.content,content_ar=excluded.content_ar,content_en=excluded.content_en,summary=excluded.summary,summary_ar=excluded.summary_ar,summary_en=excluded.summary_en,author=excluded.author,tags=excluded.tags,published=true,metadata=excluded.metadata,updated_at=now();
INSERT INTO public.articles (id,title,title_ar,title_en,slug,content,content_ar,content_en,summary,summary_ar,summary_en,author,tags,featured,published,views,metadata) VALUES ('9d606d78-ac09-5374-af75-24763054086e','خطة حفظ القرآن للمبتدئ والطالب','خطة حفظ القرآن للمبتدئ والطالب','Zikr Educational Article','zikr-article-deep-02','الحفظ النافع يحتاج إلى خطة واقعية أكثر من حاجته إلى اندفاع مؤقت. يحدد الطالب مقدارًا صغيرًا يناسب وقته، ثم يقرأ المقطع من مصحف ثابت، ويستمع إلى قارئ موثوق، ويكرر الآيات نظرًا وغيبًا، ويعرضها على معلّم أو شريك مراجعة متى تيسر. المراجعة ليست مرحلة لاحقة بل جزء من الحفظ منذ اليوم الأول؛ فالمقطع الجديد يراجع في اليوم التالي، ثم في نهاية الأسبوع، ثم ضمن دورة شهرية. ينبغي تسجيل التقدم بصدق، والتعامل مع النسيان بوصفه إشارة إلى زيادة المراجعة لا سببًا لترك المشروع. كما يجب ألا يُنسب فهم خاص للآية إلى القرآن دون الرجوع إلى التفسير المعتبر. ويمكن للمنصة أن تساعد الطالب بتتبع الآيات والصفحات والأخطاء، لكن التقييم النهائي للضبط والاستمرار يحتاج إلى ممارسة بشرية ومعلّم مؤهل.','الحفظ النافع يحتاج إلى خطة واقعية أكثر من حاجته إلى اندفاع مؤقت. يحدد الطالب مقدارًا صغيرًا يناسب وقته، ثم يقرأ المقطع من مصحف ثابت، ويستمع إلى قارئ موثوق، ويكرر الآيات نظرًا وغيبًا، ويعرضها على معلّم أو شريك مراجعة متى تيسر. المراجعة ليست مرحلة لاحقة بل جزء من الحفظ منذ اليوم الأول؛ فالمقطع الجديد يراجع في اليوم التالي، ثم في نهاية الأسبوع، ثم ضمن دورة شهرية. ينبغي تسجيل التقدم بصدق، والتعامل مع النسيان بوصفه إشارة إلى زيادة المراجعة لا سببًا لترك المشروع. كما يجب ألا يُنسب فهم خاص للآية إلى القرآن دون الرجوع إلى التفسير المعتبر. ويمكن للمنصة أن تساعد الطالب بتتبع الآيات والصفحات والأخطاء، لكن التقييم النهائي للضبط والاستمرار يحتاج إلى ممارسة بشرية ومعلّم مؤهل.',NULL,'منهج تدريجي لحفظ القرآن يعتمد على القليل المستمر والمراجعة والتلقي المنضبط.','منهج تدريجي لحفظ القرآن يعتمد على القليل المستمر والمراجعة والتلقي المنضبط.',NULL,'فريق تحرير ذِكر',ARRAY['القرآن','الحفظ','التعليم'],false,true,0,'{"editorial": true, "not_hadith_quote": true, "not_fatwa": true, "source_urls": ["https://quran.com/54/17", "https://quran.com/75/16-19"], "source_note": "Original educational article; readers should consult primary sources and qualified scholars for detailed rulings."}'::jsonb) ON CONFLICT (slug) DO UPDATE SET title=excluded.title,title_ar=excluded.title_ar,title_en=excluded.title_en,content=excluded.content,content_ar=excluded.content_ar,content_en=excluded.content_en,summary=excluded.summary,summary_ar=excluded.summary_ar,summary_en=excluded.summary_en,author=excluded.author,tags=excluded.tags,published=true,metadata=excluded.metadata,updated_at=now();
INSERT INTO public.articles (id,title,title_ar,title_en,slug,content,content_ar,content_en,summary,summary_ar,summary_en,author,tags,featured,published,views,metadata) VALUES ('3603c99c-3f05-5abc-9ac9-9956a2e3a271','الصلاة وتنظيم يوم الطالب','الصلاة وتنظيم يوم الطالب','Zikr Educational Article','zikr-article-deep-03','يستطيع الطالب أن يجعل مواقيت الصلاة علامات ثابتة في يومه بدل أن يراها فواصل تعطل الدراسة. يبدأ ذلك بضبط الوقت المحلي من مصدر موثوق، ثم تجهيز مكان هادئ، ووضع خطة للمذاكرة بين الصلوات، وإغلاق الإشعارات أثناء التركيز. لا تعني المحافظة على الصلاة إهمال المسؤوليات أو النوم والصحة، بل تساعد على توزيع الجهد والعودة إلى اليوم بعد كل محطة. ومن النافع أن يراجع الطالب في نهاية الأسبوع أسباب التأخر: هل المشكلة في النوم، أو المواصلات، أو غياب الاستعداد؟ ثم يعالج السبب بإجراء عملي. أما المسائل الفقهية التفصيلية المتعلقة بالقضاء أو الجمع أو الأعذار، فلا يُستخرج فيها حكم عام من مقال تطبيقي، بل يُسأل فيها أهل العلم الموثوقون بحسب الحال.','يستطيع الطالب أن يجعل مواقيت الصلاة علامات ثابتة في يومه بدل أن يراها فواصل تعطل الدراسة. يبدأ ذلك بضبط الوقت المحلي من مصدر موثوق، ثم تجهيز مكان هادئ، ووضع خطة للمذاكرة بين الصلوات، وإغلاق الإشعارات أثناء التركيز. لا تعني المحافظة على الصلاة إهمال المسؤوليات أو النوم والصحة، بل تساعد على توزيع الجهد والعودة إلى اليوم بعد كل محطة. ومن النافع أن يراجع الطالب في نهاية الأسبوع أسباب التأخر: هل المشكلة في النوم، أو المواصلات، أو غياب الاستعداد؟ ثم يعالج السبب بإجراء عملي. أما المسائل الفقهية التفصيلية المتعلقة بالقضاء أو الجمع أو الأعذار، فلا يُستخرج فيها حكم عام من مقال تطبيقي، بل يُسأل فيها أهل العلم الموثوقون بحسب الحال.',NULL,'أفكار عملية لربط مواقيت الصلاة بتنظيم الدراسة والمسؤوليات مع إحالة الفتوى لأهل الاختصاص.','أفكار عملية لربط مواقيت الصلاة بتنظيم الدراسة والمسؤوليات مع إحالة الفتوى لأهل الاختصاص.',NULL,'فريق تحرير ذِكر',ARRAY['الصلاة','الطلاب','تنظيم الوقت'],false,true,0,'{"editorial": true, "not_hadith_quote": true, "not_fatwa": true, "source_urls": ["https://quran.com/4/103", "https://quran.com/20/14"], "source_note": "Original educational article; readers should consult primary sources and qualified scholars for detailed rulings."}'::jsonb) ON CONFLICT (slug) DO UPDATE SET title=excluded.title,title_ar=excluded.title_ar,title_en=excluded.title_en,content=excluded.content,content_ar=excluded.content_ar,content_en=excluded.content_en,summary=excluded.summary,summary_ar=excluded.summary_ar,summary_en=excluded.summary_en,author=excluded.author,tags=excluded.tags,published=true,metadata=excluded.metadata,updated_at=now();
INSERT INTO public.articles (id,title,title_ar,title_en,slug,content,content_ar,content_en,summary,summary_ar,summary_en,author,tags,featured,published,views,metadata) VALUES ('74c1b2f7-eef0-5583-9720-4713d689af0f','الصيام بين العبادة والعادات الصحية','الصيام بين العبادة والعادات الصحية','Zikr Educational Article','zikr-article-deep-04','الصيام عبادة لها مقصد روحي وتربوي، ولا يصح اختزاله في نظام غذائي أو تجربة إنتاجية. يستعد المسلم له بالتوبة وتنظيم النوم وترتيب الالتزامات، ويحرص على عدم تحويل الإفطار إلى إسراف أو إضرار بالبدن. يحتاج المريض والمسافر وأصحاب الحالات الخاصة إلى سؤال أهل العلم والطبيب، لأن الحكم الشرعي والتقدير الصحي قد يختلفان من شخص إلى آخر. ومن الجوانب التربوية للصيام ضبط اللسان، وتقليل الجدال، وإغاثة المحتاج، وجعل وقت الطعام فرصة للشكر لا للمقارنة. وبعد انتهاء الموسم، يمكن الاحتفاظ بعادة واحدة قابلة للاستمرار مثل الصدقة أو قراءة القرآن أو صلة الرحم، حتى يظهر أثر العبادة في السلوك لا في جدول مؤقت فقط.','الصيام عبادة لها مقصد روحي وتربوي، ولا يصح اختزاله في نظام غذائي أو تجربة إنتاجية. يستعد المسلم له بالتوبة وتنظيم النوم وترتيب الالتزامات، ويحرص على عدم تحويل الإفطار إلى إسراف أو إضرار بالبدن. يحتاج المريض والمسافر وأصحاب الحالات الخاصة إلى سؤال أهل العلم والطبيب، لأن الحكم الشرعي والتقدير الصحي قد يختلفان من شخص إلى آخر. ومن الجوانب التربوية للصيام ضبط اللسان، وتقليل الجدال، وإغاثة المحتاج، وجعل وقت الطعام فرصة للشكر لا للمقارنة. وبعد انتهاء الموسم، يمكن الاحتفاظ بعادة واحدة قابلة للاستمرار مثل الصدقة أو قراءة القرآن أو صلة الرحم، حتى يظهر أثر العبادة في السلوك لا في جدول مؤقت فقط.',NULL,'مقاربة تربوية للصيام توازن بين العبادة، حفظ الصحة، وتقليل الإسراف دون تقديم فتوى شخصية.','مقاربة تربوية للصيام توازن بين العبادة، حفظ الصحة، وتقليل الإسراف دون تقديم فتوى شخصية.',NULL,'فريق تحرير ذِكر',ARRAY['الصيام','التزكية','الصحة'],false,true,0,'{"editorial": true, "not_hadith_quote": true, "not_fatwa": true, "source_urls": ["https://quran.com/2/183", "https://quran.com/2/185"], "source_note": "Original educational article; readers should consult primary sources and qualified scholars for detailed rulings."}'::jsonb) ON CONFLICT (slug) DO UPDATE SET title=excluded.title,title_ar=excluded.title_ar,title_en=excluded.title_en,content=excluded.content,content_ar=excluded.content_ar,content_en=excluded.content_en,summary=excluded.summary,summary_ar=excluded.summary_ar,summary_en=excluded.summary_en,author=excluded.author,tags=excluded.tags,published=true,metadata=excluded.metadata,updated_at=now();
INSERT INTO public.articles (id,title,title_ar,title_en,slug,content,content_ar,content_en,summary,summary_ar,summary_en,author,tags,featured,published,views,metadata) VALUES ('038dfcb2-a988-5c15-a9a8-f968ee29e982','بر الوالدين وصلة الرحم في الحياة اليومية','بر الوالدين وصلة الرحم في الحياة اليومية','Zikr Educational Article','zikr-article-deep-05','تظهر صلة الرحم في أعمال صغيرة متكررة: سؤال صادق، مساعدة عملية، حفظ للخصوصية، وزيارة تناسب قدرة الطرفين. بر الوالدين لا يلغي الحوار ولا يبرر الظلم، لكنه يطلب أدبًا ورحمة واختيارًا حسنًا للكلمة، مع الاستعانة بوسيط حكيم عند النزاع. يمكن للأسرة أن تنشئ قائمة أسبوعية للاتصال بالأقارب، وأن تعلم الأطفال أن صلة الرحم ليست مناسبة موسمية. وعند وجود مرض أو مسافة أو خلاف شديد، قد تكون الرسالة اللطيفة أو المساعدة غير المباشرة بداية مناسبة. لا تنسب كل قصة عائلية إلى حكم شرعي عام؛ فحقوق الناس وتفاصيل الضرر تحتاج إلى استشارة متخصصة تحفظ الدين والواقع معًا.','تظهر صلة الرحم في أعمال صغيرة متكررة: سؤال صادق، مساعدة عملية، حفظ للخصوصية، وزيارة تناسب قدرة الطرفين. بر الوالدين لا يلغي الحوار ولا يبرر الظلم، لكنه يطلب أدبًا ورحمة واختيارًا حسنًا للكلمة، مع الاستعانة بوسيط حكيم عند النزاع. يمكن للأسرة أن تنشئ قائمة أسبوعية للاتصال بالأقارب، وأن تعلم الأطفال أن صلة الرحم ليست مناسبة موسمية. وعند وجود مرض أو مسافة أو خلاف شديد، قد تكون الرسالة اللطيفة أو المساعدة غير المباشرة بداية مناسبة. لا تنسب كل قصة عائلية إلى حكم شرعي عام؛ فحقوق الناس وتفاصيل الضرر تحتاج إلى استشارة متخصصة تحفظ الدين والواقع معًا.',NULL,'تطبيقات يومية لصلة الرحم وبر الوالدين مع مراعاة الحدود والخصوصية وطلب الاستشارة عند النزاع.','تطبيقات يومية لصلة الرحم وبر الوالدين مع مراعاة الحدود والخصوصية وطلب الاستشارة عند النزاع.',NULL,'فريق تحرير ذِكر',ARRAY['الأسرة','الأخلاق','صلة الرحم'],false,true,0,'{"editorial": true, "not_hadith_quote": true, "not_fatwa": true, "source_urls": ["https://quran.com/17/23-24", "https://quran.com/4/36"], "source_note": "Original educational article; readers should consult primary sources and qualified scholars for detailed rulings."}'::jsonb) ON CONFLICT (slug) DO UPDATE SET title=excluded.title,title_ar=excluded.title_ar,title_en=excluded.title_en,content=excluded.content,content_ar=excluded.content_ar,content_en=excluded.content_en,summary=excluded.summary,summary_ar=excluded.summary_ar,summary_en=excluded.summary_en,author=excluded.author,tags=excluded.tags,published=true,metadata=excluded.metadata,updated_at=now();
INSERT INTO public.articles (id,title,title_ar,title_en,slug,content,content_ar,content_en,summary,summary_ar,summary_en,author,tags,featured,published,views,metadata) VALUES ('1e058b4a-68c5-5272-b97d-ce60894b9f3e','حقوق الجار وبناء المجتمع الآمن','حقوق الجار وبناء المجتمع الآمن','Zikr Educational Article','zikr-article-deep-06','حق الجار يظهر في كف الأذى قبل كثرة المجاملات: احترام الهدوء، عدم إغلاق الممرات، رد الأمانة، مراعاة كبار السن، والتواصل عند الطوارئ. وفي العمارة أو الحي يمكن للسكان الاتفاق على قواعد واضحة للنظافة والضوضاء ومواقف السيارات، لأن حسن الجوار يحتاج إلى تنظيم لا إلى نوايا فقط. إذا وقع خلاف، يبدأ الإصلاح بسؤال هادئ ووصف السلوك دون اتهام النيات، ثم الاستعانة بإدارة المكان أو وسيط عند الحاجة. ويجب ألا تتحول نصائح الجوار إلى اقتحام للخصوصية أو نشر أخبار البيوت. هذه المعاني تربي على الرحمة والعدل، وتربط العبادة بسلوك يلمسه الناس في الشارع والعمل والسكن.','حق الجار يظهر في كف الأذى قبل كثرة المجاملات: احترام الهدوء، عدم إغلاق الممرات، رد الأمانة، مراعاة كبار السن، والتواصل عند الطوارئ. وفي العمارة أو الحي يمكن للسكان الاتفاق على قواعد واضحة للنظافة والضوضاء ومواقف السيارات، لأن حسن الجوار يحتاج إلى تنظيم لا إلى نوايا فقط. إذا وقع خلاف، يبدأ الإصلاح بسؤال هادئ ووصف السلوك دون اتهام النيات، ثم الاستعانة بإدارة المكان أو وسيط عند الحاجة. ويجب ألا تتحول نصائح الجوار إلى اقتحام للخصوصية أو نشر أخبار البيوت. هذه المعاني تربي على الرحمة والعدل، وتربط العبادة بسلوك يلمسه الناس في الشارع والعمل والسكن.',NULL,'دليل سلوكي لحفظ حق الجار وتقليل الأذى وبناء قواعد تعاون داخل الحي.','دليل سلوكي لحفظ حق الجار وتقليل الأذى وبناء قواعد تعاون داخل الحي.',NULL,'فريق تحرير ذِكر',ARRAY['الأخلاق','المجتمع','الرحمة'],false,true,0,'{"editorial": true, "not_hadith_quote": true, "not_fatwa": true, "source_urls": ["https://quran.com/4/36", "https://quran.com/49/11-12"], "source_note": "Original educational article; readers should consult primary sources and qualified scholars for detailed rulings."}'::jsonb) ON CONFLICT (slug) DO UPDATE SET title=excluded.title,title_ar=excluded.title_ar,title_en=excluded.title_en,content=excluded.content,content_ar=excluded.content_ar,content_en=excluded.content_en,summary=excluded.summary,summary_ar=excluded.summary_ar,summary_en=excluded.summary_en,author=excluded.author,tags=excluded.tags,published=true,metadata=excluded.metadata,updated_at=now();
INSERT INTO public.articles (id,title,title_ar,title_en,slug,content,content_ar,content_en,summary,summary_ar,summary_en,author,tags,featured,published,views,metadata) VALUES ('f4a308a2-053e-5dd0-9f43-ed8d7f106170','منهج قراءة السيرة والتمييز بين الثابت والمشهور','منهج قراءة السيرة والتمييز بين الثابت والمشهور','Zikr Educational Article','zikr-article-deep-07','قراءة السيرة النبوية تحتاج إلى جمع بين محبة النبي صلى الله عليه وسلم والانضباط في نسبة الأخبار. يبدأ الباحث بتحديد الكتاب والباب والراوي أو المصدر، ثم يقارن الخبر بالمصادر التي تهتم بدرجة الرواية، ويفصل بين الحدث الثابت والتفاصيل التي شاعت في المواعظ دون توثيق كاف. ولا تُقرأ السيرة بوصفها سجل معارك فقط؛ ففيها بناء الأسرة، والوفاء بالعهد، وإدارة الأزمات، والتعليم، والرحمة، والتعامل مع المختلف. عند إعداد بحث مدرسي، يكتب الطالب المرجع كاملًا، ويضع علامة على ما يحتاج إلى مزيد من التحقق، ولا يملأ الفجوات بحوار أو تاريخ دقيق لم يذكره المصدر. بهذه الطريقة يصبح المحتوى مفيدًا ومحترمًا للعلم بدل أن يتحول إلى قصة أدبية منسوبة للدين.','قراءة السيرة النبوية تحتاج إلى جمع بين محبة النبي صلى الله عليه وسلم والانضباط في نسبة الأخبار. يبدأ الباحث بتحديد الكتاب والباب والراوي أو المصدر، ثم يقارن الخبر بالمصادر التي تهتم بدرجة الرواية، ويفصل بين الحدث الثابت والتفاصيل التي شاعت في المواعظ دون توثيق كاف. ولا تُقرأ السيرة بوصفها سجل معارك فقط؛ ففيها بناء الأسرة، والوفاء بالعهد، وإدارة الأزمات، والتعليم، والرحمة، والتعامل مع المختلف. عند إعداد بحث مدرسي، يكتب الطالب المرجع كاملًا، ويضع علامة على ما يحتاج إلى مزيد من التحقق، ولا يملأ الفجوات بحوار أو تاريخ دقيق لم يذكره المصدر. بهذه الطريقة يصبح المحتوى مفيدًا ومحترمًا للعلم بدل أن يتحول إلى قصة أدبية منسوبة للدين.',NULL,'منهج بحثي لقراءة السيرة مع التمييز بين الرواية الموثقة والتفاصيل الشعبية.','منهج بحثي لقراءة السيرة مع التمييز بين الرواية الموثقة والتفاصيل الشعبية.',NULL,'فريق تحرير ذِكر',ARRAY['السيرة','البحث','المصادر'],false,true,0,'{"editorial": true, "not_hadith_quote": true, "not_fatwa": true, "source_urls": ["https://quran.com/33/21", "https://sunnah.com/developers"], "source_note": "Original educational article; readers should consult primary sources and qualified scholars for detailed rulings."}'::jsonb) ON CONFLICT (slug) DO UPDATE SET title=excluded.title,title_ar=excluded.title_ar,title_en=excluded.title_en,content=excluded.content,content_ar=excluded.content_ar,content_en=excluded.content_en,summary=excluded.summary,summary_ar=excluded.summary_ar,summary_en=excluded.summary_en,author=excluded.author,tags=excluded.tags,published=true,metadata=excluded.metadata,updated_at=now();
INSERT INTO public.articles (id,title,title_ar,title_en,slug,content,content_ar,content_en,summary,summary_ar,summary_en,author,tags,featured,published,views,metadata) VALUES ('96f1e365-df05-5196-824e-fc9ce2e23386','التعامل مع الحديث: التخريج والدرجة والسياق','التعامل مع الحديث: التخريج والدرجة والسياق','Zikr Educational Article','zikr-article-deep-08','لا يكفي أن يظهر نص حديث في صورة جميلة حتى يصح نشره. يتتبع الباحث اسم الكتاب ورقم الحديث واللفظ، ويتحقق من درجة الرواية من المصدر الذي يذكرها، ويفرق بين الحديث المرفوع وكلام الصحابي والشرح المعاصر. كما يقرأ السياق، لأن اقتطاع جملة قد يغير المقصود، ولا يحول درجة الصحة وحدها دون فهم اللغة والباب الذي ورد فيه النص. إذا اختلفت أحكام المحدثين، ينقل الباحث الخلاف بأمانة ولا يختار النتيجة التي توافق رغبته. وتوضح Sunnah.com أن واجهة API لديها جزء من البيانات وتخضع لمراجعة يدوية وتحتاج إلى مفتاح؛ لذلك لا يجوز للمنصة أن تستخدم scraping أو مصدرًا مجهولًا ثم تسميه قاعدة حديث رسمية.','لا يكفي أن يظهر نص حديث في صورة جميلة حتى يصح نشره. يتتبع الباحث اسم الكتاب ورقم الحديث واللفظ، ويتحقق من درجة الرواية من المصدر الذي يذكرها، ويفرق بين الحديث المرفوع وكلام الصحابي والشرح المعاصر. كما يقرأ السياق، لأن اقتطاع جملة قد يغير المقصود، ولا يحول درجة الصحة وحدها دون فهم اللغة والباب الذي ورد فيه النص. إذا اختلفت أحكام المحدثين، ينقل الباحث الخلاف بأمانة ولا يختار النتيجة التي توافق رغبته. وتوضح Sunnah.com أن واجهة API لديها جزء من البيانات وتخضع لمراجعة يدوية وتحتاج إلى مفتاح؛ لذلك لا يجوز للمنصة أن تستخدم scraping أو مصدرًا مجهولًا ثم تسميه قاعدة حديث رسمية.',NULL,'دليل تحقق حديثي يشرح التوثيق والدرجة والسياق وحدود الاستيراد الآلي.','دليل تحقق حديثي يشرح التوثيق والدرجة والسياق وحدود الاستيراد الآلي.',NULL,'فريق تحرير ذِكر',ARRAY['الحديث','التخريج','التحقق'],false,true,0,'{"editorial": true, "not_hadith_quote": true, "not_fatwa": true, "source_urls": ["https://sunnah.com/developers", "https://sunnah.com/about"], "source_note": "Original educational article; readers should consult primary sources and qualified scholars for detailed rulings."}'::jsonb) ON CONFLICT (slug) DO UPDATE SET title=excluded.title,title_ar=excluded.title_ar,title_en=excluded.title_en,content=excluded.content,content_ar=excluded.content_ar,content_en=excluded.content_en,summary=excluded.summary,summary_ar=excluded.summary_ar,summary_en=excluded.summary_en,author=excluded.author,tags=excluded.tags,published=true,metadata=excluded.metadata,updated_at=now();
INSERT INTO public.articles (id,title,title_ar,title_en,slug,content,content_ar,content_en,summary,summary_ar,summary_en,author,tags,featured,published,views,metadata) VALUES ('c53afb35-91e0-52ea-9165-e3a2010c933c','القبلة ومواقيت الصلاة: التقنية لا تلغي التحقق','القبلة ومواقيت الصلاة: التقنية لا تلغي التحقق','Zikr Educational Article','zikr-article-deep-09','تستخدم تطبيقات القبلة والصلاة الإحداثيات والوقت والمنطقة الزمنية وحسابات فلكية، ولذلك ينبغي للمستخدم أن يراجع إعداد المدينة والاتجاه الجغرافي والوقت الصيفي. قد يظهر اختلاف بسيط بين طرق الحساب أو بين موقع وآخر، فيختار المسلم إعدادًا موثقًا ويتعلم الطريقة بدل تبديل النتائج عشوائيًا. في الأماكن المغلقة يساعد التحقق من الاتجاه العام، وفي السفر قد يحتاج إلى سؤال أهل المكان. أما الأعذار والأحكام الخاصة بتغير الوقت أو الجمع والقصر فليست نتيجة رقمية تلقائية، وتحتاج إلى معرفة الحال وسؤال أهل العلم. وظيفة التقنية أن تسهّل الوصول إلى المعلومة وتعرض طريقة الحساب بوضوح، لا أن تدعي أنها تفتي في كل حالة.','تستخدم تطبيقات القبلة والصلاة الإحداثيات والوقت والمنطقة الزمنية وحسابات فلكية، ولذلك ينبغي للمستخدم أن يراجع إعداد المدينة والاتجاه الجغرافي والوقت الصيفي. قد يظهر اختلاف بسيط بين طرق الحساب أو بين موقع وآخر، فيختار المسلم إعدادًا موثقًا ويتعلم الطريقة بدل تبديل النتائج عشوائيًا. في الأماكن المغلقة يساعد التحقق من الاتجاه العام، وفي السفر قد يحتاج إلى سؤال أهل المكان. أما الأعذار والأحكام الخاصة بتغير الوقت أو الجمع والقصر فليست نتيجة رقمية تلقائية، وتحتاج إلى معرفة الحال وسؤال أهل العلم. وظيفة التقنية أن تسهّل الوصول إلى المعلومة وتعرض طريقة الحساب بوضوح، لا أن تدعي أنها تفتي في كل حالة.',NULL,'شرح عملي لاستخدام أدوات القبلة والصلاة مع مراجعة الإعدادات وإحالة الأحكام الخاصة للعلماء.','شرح عملي لاستخدام أدوات القبلة والصلاة مع مراجعة الإعدادات وإحالة الأحكام الخاصة للعلماء.',NULL,'فريق تحرير ذِكر',ARRAY['الصلاة','القبلة','التقنية'],false,true,0,'{"editorial": true, "not_hadith_quote": true, "not_fatwa": true, "source_urls": ["https://quran.com/2/144", "https://quran.com/4/103"], "source_note": "Original educational article; readers should consult primary sources and qualified scholars for detailed rulings."}'::jsonb) ON CONFLICT (slug) DO UPDATE SET title=excluded.title,title_ar=excluded.title_ar,title_en=excluded.title_en,content=excluded.content,content_ar=excluded.content_ar,content_en=excluded.content_en,summary=excluded.summary,summary_ar=excluded.summary_ar,summary_en=excluded.summary_en,author=excluded.author,tags=excluded.tags,published=true,metadata=excluded.metadata,updated_at=now();
INSERT INTO public.articles (id,title,title_ar,title_en,slug,content,content_ar,content_en,summary,summary_ar,summary_en,author,tags,featured,published,views,metadata) VALUES ('47906c72-7c15-5acf-a609-b36b0777f3cf','الذكر والدعاء: النص المأثور والصياغة التعليمية','الذكر والدعاء: النص المأثور والصياغة التعليمية','Zikr Educational Article','zikr-article-deep-10','يفرق المحتوى المسؤول بين الدعاء المأثور الذي ينسب إلى القرآن أو السنة مع مرجعه، وبين دعاء عام يصوغه الكاتب للتذكير ولا ينسبه إلى نص شرعي. هذه التفرقة تحمي القارئ من الخلط، وتمنحه مساحة للدعاء بلغته فيما لا يتضمن محذورًا، مع احترام النصوص الثابتة. عند نشر ذكر بعدد أو وقت أو فضيلة محددة، يلزم ذكر المصدر ودرجة الحديث عند الحاجة، ولا تكفي عبارة "مجرّب" أو صورة متداولة. ويمكن للمنصة أن تعرض النص، ومصدره، وشرحًا عامًا لطريقة الاستفادة، مع تنبيه أن الدعاء لا يغني عن العلاج أو رد الحقوق أو العمل بالأسباب.','يفرق المحتوى المسؤول بين الدعاء المأثور الذي ينسب إلى القرآن أو السنة مع مرجعه، وبين دعاء عام يصوغه الكاتب للتذكير ولا ينسبه إلى نص شرعي. هذه التفرقة تحمي القارئ من الخلط، وتمنحه مساحة للدعاء بلغته فيما لا يتضمن محذورًا، مع احترام النصوص الثابتة. عند نشر ذكر بعدد أو وقت أو فضيلة محددة، يلزم ذكر المصدر ودرجة الحديث عند الحاجة، ولا تكفي عبارة "مجرّب" أو صورة متداولة. ويمكن للمنصة أن تعرض النص، ومصدره، وشرحًا عامًا لطريقة الاستفادة، مع تنبيه أن الدعاء لا يغني عن العلاج أو رد الحقوق أو العمل بالأسباب.',NULL,'سياسة تحريرية لتمييز الأدعية المأثورة عن الصياغات التعليمية وحفظ المصدر والدرجة.','سياسة تحريرية لتمييز الأدعية المأثورة عن الصياغات التعليمية وحفظ المصدر والدرجة.',NULL,'فريق تحرير ذِكر',ARRAY['الدعاء','الأذكار','التحرير'],false,true,0,'{"editorial": true, "not_hadith_quote": true, "not_fatwa": true, "source_urls": ["https://quran.com/40/60", "https://sunnah.com/developers"], "source_note": "Original educational article; readers should consult primary sources and qualified scholars for detailed rulings."}'::jsonb) ON CONFLICT (slug) DO UPDATE SET title=excluded.title,title_ar=excluded.title_ar,title_en=excluded.title_en,content=excluded.content,content_ar=excluded.content_ar,content_en=excluded.content_en,summary=excluded.summary,summary_ar=excluded.summary_ar,summary_en=excluded.summary_en,author=excluded.author,tags=excluded.tags,published=true,metadata=excluded.metadata,updated_at=now();
INSERT INTO public.articles (id,title,title_ar,title_en,slug,content,content_ar,content_en,summary,summary_ar,summary_en,author,tags,featured,published,views,metadata) VALUES ('6fc62a2f-0c58-501f-91c8-c85fd2396f85','العمل والرزق والأمانة المهنية','العمل والرزق والأمانة المهنية','Zikr Educational Article','zikr-article-deep-11','الأمانة المهنية ليست شعارًا دينيًا منفصلًا عن المهارة؛ فهي تشمل الصدق في السيرة الذاتية، وضبط الوقت، وحماية بيانات العملاء، والإبلاغ عن الخطأ، ورفض التلاعب في التقارير. يوازن المسلم بين طلب الرزق وحقوق الأسرة والبدن، ولا يجعل الانشغال عذرًا دائمًا لترك الفرائض أو ظلم الزملاء. في المشاريع التجارية يسجل الاتفاقات بوضوح، ويفصل بين المال الشخصي ومال المؤسسة، ويطلب مشورة متخصصة في العقود والضرائب والتمويل بدل إطلاق أحكام عامة من مقال قصير. بهذا تصبح القيم الدينية قابلة للقياس في السلوك، لا مجرد عبارات في صفحة تعريفية.','الأمانة المهنية ليست شعارًا دينيًا منفصلًا عن المهارة؛ فهي تشمل الصدق في السيرة الذاتية، وضبط الوقت، وحماية بيانات العملاء، والإبلاغ عن الخطأ، ورفض التلاعب في التقارير. يوازن المسلم بين طلب الرزق وحقوق الأسرة والبدن، ولا يجعل الانشغال عذرًا دائمًا لترك الفرائض أو ظلم الزملاء. في المشاريع التجارية يسجل الاتفاقات بوضوح، ويفصل بين المال الشخصي ومال المؤسسة، ويطلب مشورة متخصصة في العقود والضرائب والتمويل بدل إطلاق أحكام عامة من مقال قصير. بهذا تصبح القيم الدينية قابلة للقياس في السلوك، لا مجرد عبارات في صفحة تعريفية.',NULL,'إرشادات في الأمانة المهنية وإدارة الرزق والبيانات والاتفاقات دون تقديم استشارة مالية شخصية.','إرشادات في الأمانة المهنية وإدارة الرزق والبيانات والاتفاقات دون تقديم استشارة مالية شخصية.',NULL,'فريق تحرير ذِكر',ARRAY['الأمانة','العمل','المعاملات'],false,true,0,'{"editorial": true, "not_hadith_quote": true, "not_fatwa": true, "source_urls": ["https://quran.com/4/58", "https://quran.com/28/26"], "source_note": "Original educational article; readers should consult primary sources and qualified scholars for detailed rulings."}'::jsonb) ON CONFLICT (slug) DO UPDATE SET title=excluded.title,title_ar=excluded.title_ar,title_en=excluded.title_en,content=excluded.content,content_ar=excluded.content_ar,content_en=excluded.content_en,summary=excluded.summary,summary_ar=excluded.summary_ar,summary_en=excluded.summary_en,author=excluded.author,tags=excluded.tags,published=true,metadata=excluded.metadata,updated_at=now();
INSERT INTO public.articles (id,title,title_ar,title_en,slug,content,content_ar,content_en,summary,summary_ar,summary_en,author,tags,featured,published,views,metadata) VALUES ('69766f6c-67f9-5777-a815-93ef7b534763','الرحمة والصحة النفسية وطلب المساعدة','الرحمة والصحة النفسية وطلب المساعدة','Zikr Educational Article','zikr-article-deep-12','الرحمة بالنفس لا تعني تبرير الخطأ، كما أن التدين لا يطلب من الإنسان إنكار التعب أو إخفاء المرض. ينظم المسلم نومه وغذاءه وعلاقاته، ويستخدم الذكر والصلاة والدعاء كأعمال روحية، مع طلب العلاج النفسي أو الطبي عند استمرار الأعراض أو وجود خطر. لا يجوز للمنصة أن تشخص حالة مستخدم أو تعده بزوال مرضه بذكر معين، ولا أن تقدم فتوى بديلة عن الطبيب أو العالم. ويمكن للمحتوى أن يشجع على التواصل الآمن، ومساندة الأسرة، وتجنب العزلة، وطلب الطوارئ عند خطر مباشر. هذه اللغة تجمع بين الإيمان وحفظ النفس وتحترم حدود المنصة.','الرحمة بالنفس لا تعني تبرير الخطأ، كما أن التدين لا يطلب من الإنسان إنكار التعب أو إخفاء المرض. ينظم المسلم نومه وغذاءه وعلاقاته، ويستخدم الذكر والصلاة والدعاء كأعمال روحية، مع طلب العلاج النفسي أو الطبي عند استمرار الأعراض أو وجود خطر. لا يجوز للمنصة أن تشخص حالة مستخدم أو تعده بزوال مرضه بذكر معين، ولا أن تقدم فتوى بديلة عن الطبيب أو العالم. ويمكن للمحتوى أن يشجع على التواصل الآمن، ومساندة الأسرة، وتجنب العزلة، وطلب الطوارئ عند خطر مباشر. هذه اللغة تجمع بين الإيمان وحفظ النفس وتحترم حدود المنصة.',NULL,'محتوى توعوي يربط الرحمة وحفظ النفس بالدعم المختص دون تشخيص أو وعود علاجية دينية.','محتوى توعوي يربط الرحمة وحفظ النفس بالدعم المختص دون تشخيص أو وعود علاجية دينية.',NULL,'فريق تحرير ذِكر',ARRAY['الرحمة','الصحة النفسية','الدعم'],false,true,0,'{"editorial": true, "not_hadith_quote": true, "not_fatwa": true, "source_urls": ["https://quran.com/2/195", "https://quran.com/4/29"], "source_note": "Original educational article; readers should consult primary sources and qualified scholars for detailed rulings."}'::jsonb) ON CONFLICT (slug) DO UPDATE SET title=excluded.title,title_ar=excluded.title_ar,title_en=excluded.title_en,content=excluded.content,content_ar=excluded.content_ar,content_en=excluded.content_en,summary=excluded.summary,summary_ar=excluded.summary_ar,summary_en=excluded.summary_en,author=excluded.author,tags=excluded.tags,published=true,metadata=excluded.metadata,updated_at=now();
